static void atp_timed_checker(struct timer_list *t)
{
	struct net_local *lp = from_timer(lp, t, timer);
	struct net_device *dev = lp->dev;
	long ioaddr = dev->base_addr;
	int tickssofar = jiffies - lp->last_rx_time;
	int i;

